import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Instrument Panel","description":"","frontmatter":{},"headers":[],"relativePath":"tr/qgc-user-guide/fly_view/instrument_panel.md","filePath":"tr/qgc-user-guide/fly_view/instrument_panel.md"}`),a={name:`tr/qgc-user-guide/fly_view/instrument_panel.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="instrument-panel" tabindex="-1">Instrument Panel <a class="header-anchor" href="#instrument-panel" aria-label="Permalink to “Instrument Panel”">​</a></h1><p>The instrument panel displays telemetry information about the current vehicle.</p><p>The default values include altitude (relative to the home location), horizontal and vertical speed, total flight time, and distance between vehicle and ground station.</p><p>You can configure where the information is displayed by:</p><ul><li>Tablets: Press and hold over control</li><li>Desktop: Right click control</li><li>Click to Lock icon to close and save changes</li></ul><p>You configure what information is display by selecting the edit/pencil icon. The grid will then display &quot;+&quot; and &quot;-&quot; icons that you can use to add or remove rows and columns (and the pencil icon is replaced by a &quot;lock&quot; icon that you can use to save the settings).</p><p>Select a value to launch its &quot;Value Display&quot; editor. This allows you to change the icon, text, size, units and so on of the current telemetry value.</p><p>The selection list on the top left is used to change the source of the telemetry. By default this is the vehicle, but you can use the selector to choose a particular sensor type.</p><p>The selection list on the top right is used to select a particular telemetry value for the vehicle or sensor.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};